# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps

def spans(*texts):
    return [parse_span(text) for text in texts]

class GapTests(unittest.TestCase):
    def test_gap_between_shifts(self):
        worked = spans("09:00-12:00", "13:00-17:00")
        self.assertEqual(
            find_gaps(worked, parse_span("09:00-17:00")),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_edges_and_overlaps(self):
        worked = spans("10:00-12:00", "11:00-13:00")
        self.assertEqual(
            find_gaps(worked, parse_span("09:00-14:00")),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 13:00-14:00 (60 min)"
            ]
        )

    def test_no_gaps(self):
        worked = spans("09:00-17:00")
        opening = parse_span("09:00-17:00")
        self.assertEqual(find_gaps(worked, opening), [])

    def test_nobody_working(self):
        self.assertEqual(
            find_gaps([], parse_span("09:00-10:00")),
            ["gap 09:00-10:00 (60 min)"]
        )

    def test_outside_opening_hours(self):
        worked = spans("08:00-12:00")
        with self.assertRaises(ValueError):
            find_gaps(worked, parse_span("09:00-17:00"))

if __name__ == "__main__":
    unittest.main()
